Item.method_code:
// IOMの取得
var iomInv = aras.IomInnovator;

// マルQページの取得
var maruQPage = aras.getItemById("h4_MQPage", itemId);

// h4_model_nameの値を取得する
var projectId = aras.getItemProperty(maruQPage, "h4_model_name");

// h4_model_nameに設定されたProjectアイテムのMYを取得する
var projectItem = iomInv.newItem("HRDPMTypModelProject", "get");
projectItem.setAttribute("select", "iq_model_year");
projectItem.setProperty("id", projectId);
projectItem = projectItem.apply();

// h4_myに取得したMYの値を設定する
var myValue = projectItem.getProperty("iq_model_year", "");
aras.setItemProperty(maruQPage, "h4_my", myValue);

return;
